import java.io.*;import java.util.*;import java.util.logging.Logger;
import org.bukkit.*;import org.bukkit.entity.*;import org.bukkit.persistence.*;import org.bukkit.plugin.Plugin;import org.bukkit.util.Transformation;
import ru.rooyzee.elytrixtalisman.service.HologramService;
public class HologramTest {
 static class Plug implements Plugin {public File getDataFolder(){return new File(".");}public Logger getLogger(){return Logger.getLogger("hologram-test");}}
 static class EntityBase implements Entity {boolean valid=true,persistent=true;Location loc;EntityBase(Location l){loc=l;}public UUID getUniqueId(){return UUID.randomUUID();}public void remove(){valid=false;}public boolean isValid(){return valid;}public void setGravity(boolean b){}public void setPersistent(boolean b){persistent=b;}public void setInvulnerable(boolean b){}public boolean teleport(Location l){loc=l;return true;}public Location getLocation(){return loc;}public PersistentDataContainer getPersistentDataContainer(){return new PersistentDataContainer(){public <P,C>boolean has(NamespacedKey k,PersistentDataType<P,C> t){return true;}};}}
 static class Text extends EntityBase implements TextDisplay {String text="";boolean shadow,defaultBg=true;Text(Location l){super(l);}public void setBillboard(Display.Billboard b){}public void setTransformation(Transformation t){}public void setInterpolationDuration(int t){}public void setTeleportDuration(int t){}public void setBrightness(Display.Brightness b){}public void setDefaultBackground(boolean b){defaultBg=b;}public void setBackgroundColor(Color c){}public void setShadowed(boolean b){shadow=b;}public void setSeeThrough(boolean b){}public void setTextOpacity(byte b){}public void setLineWidth(int n){}public void setText(String s){text=s;}}
 static class Stand extends EntityBase implements ArmorStand {Stand(Location l){super(l);}}
 static class W implements World {boolean loaded=true;List<Text> texts=new ArrayList<>();List<Entity> legacy=new ArrayList<>();int chunkReads;public boolean isChunkLoaded(int x,int z){return loaded&&x==0&&z==0;}public Chunk getChunkAt(int x,int z){if(!isChunkLoaded(x,z))throw new AssertionError("forced chunk");chunkReads++;return ()->legacy.toArray(new Entity[0]);}@SuppressWarnings("unchecked")public <T extends Entity>T spawn(Location l,Class<T> type){Text t=new Text(l);texts.add(t);return (T)t;}public <T>void spawnParticle(Particle p,Location l,int n,double x,double y,double z,double s,T data){}}
 static void check(boolean b){if(!b)throw new AssertionError();}
 public static void main(String[]args){W w=new W();HologramService h=new HologramService(new Plug());Location l=new Location(w,5,70,5);h.create(l,Arrays.asList("&aТАЛИСМАН","%top1%","&fДо лута: %points%"));check(h.isAlive()&&w.texts.size()==2);Text body=w.texts.get(0),title=w.texts.get(1);check(!body.persistent&&!title.persistent&&title.shadow&&body.shadow&&!body.defaultBg&&!title.defaultBg);check(title.text.contains("ТАЛИСМАН")&&!body.text.contains("%top1%"));Map<String,String> map=new HashMap<>();map.put("%top1%","&fКлан А");map.put("%points%","37");h.update(map);check(body.text.contains("Клан А")&&body.text.contains("37")&&w.texts.size()==2);body.valid=false;h.update(map);check(w.texts.size()==4&&!title.valid&&h.isAlive());Text next=w.texts.get(2);w.loaded=false;next.valid=false;h.update(map);check(!h.isAlive()&&w.texts.size()==4);w.loaded=true;h.update(map);check(h.isAlive()&&w.texts.size()==6);Stand near=new Stand(new Location(w,6,70,5)),far=new Stand(new Location(w,60,70,5));w.legacy.add(near);w.legacy.add(far);h.destroy();check(!near.valid&&far.valid&&!h.isAlive()&&h.getBase()==null);System.out.println("Hologram updates, recovery, cleanup and legacy scope OK");}
}
